Here are modern MSTest data-driven tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- CalculateTotal: DataRow for inline cases ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00, DisplayName = "Single item")]
    [DataRow(5, 20.00, 100.00, DisplayName = "Multiple items")]
    [DataRow(0, 15.00, 0.00, DisplayName = "Zero quantity")]
    [DataRow(3, 0.00, 0.00, DisplayName = "Zero price")]
    [DataRow(1, 99.99, 99.99, DisplayName = "Fractional price")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(-1, 10m));
    }

    // --- ApplyDiscount: DynamicData with ValueTuples for complex cases ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (99.99m, 50, 49.995m),
    ];

    [TestMethod]
    [DataRow(-1)]
    [DataRow(101)]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(int percent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, percent));
    }

    [TestMethod]
    public void ApplyDiscount_NegativePrice_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(-10m, 10));
    }
}
```

**Key patterns used:**

- **`[DataRow]`** — inline data for simple primitive inputs (`CalculateTotal` happy paths, invalid percent boundary cases)
- **`[DynamicData]` with ValueTuples** — type-safe complex data with named parameters (MSTest 3.7+), preferred over `IEnumerable<object[]>`
- **`Assert.ThrowsExactly<T>`** — modern exception testing instead of `[ExpectedException]`
- **Sealed class**, constructor init, AAA pattern, `MethodName_Scenario_Expected` naming

> **Note:** `DataRow` can't accept `decimal` literals directly (they're not compile-time constants), so `double` is used with a cast. `DynamicData` avoids this limitation entirely — prefer it when you need `decimal` precision.

For your project file, use `MSTest.Sdk` for the simplest setup:

```xml
<Project Sdk="MSTest.Sdk">
  <PropertyGroup>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
</Project>
```
